function refRight(){const r=$('rRight');if(S.mode==='msg'&&S.doc!=null){const o=otherOf(S.doc);r.innerHTML=o>=0?`<button class="swap" id="swTop">⇄ ${D.meta[o][2]==='VGR'?'VGR':'Shekinah'}</button>`:'<div class="para-ic">§</div>';if(o>=0)$('swTop').onclick=ev=>{ev.stopPropagation();swapTrad()}}else r.innerHTML='<div class="para-ic">§</div>'}
function refbar(){refRight();
  if(S.mode==='bible'){const b=D.books[S.book];const n=b[1][S.chap-1].length;let nl=0;for(let v=1;v<=n;v++)nl+=linksOfVi(viOf(S.book,S.chap,v)).length;
    $('rLetter').textContent=b[0].replace(/^\d\s*/,'')[0];$('rTitle').innerHTML=`${esc(b[0])} ${S.chap} <span style="opacity:.4">▼</span>`;$('rSub').textContent=`${n} versets • ${nl.toLocaleString('fr')} paragraphes liés • Parallèle activé`}
  else if(S.doc!=null){const m=D.meta[S.doc];$('rLetter').textContent=m[2]==='VGR'?'V':'S';$('rTitle').innerHTML=`${m[0]} — ${esc(m[1])}`;$('rSub').innerHTML=`${m[2]==='VGR'?'VGR':'Shekinah'} • ${m[3]} • <b id="curP">§ ${S.curP||1}</b> / ${m[5]}`}
  else{$('rLetter').textContent='M';$('rTitle').innerHTML='Brochures <span style="opacity:.4">▼</span>';$('rSub').textContent=`${D.codes.toLocaleString('fr')} prédications • ${D.meta.length.toLocaleString('fr')} textes (Shekinah + VGR)`}
}

// ---------- vue Bible
function renderBible(flashV){
  const b=D.books[S.book],vs=b[1][S.chap-1];let h='';
  vs.forEach((t,k)=>{const v=k+1,vi=viOf(S.book,S.chap,v),L=linksOfVi(vi);const key=L.length>=25;
    const ch=L.slice().sort(sortLinks).slice(0,3).map((li,j)=>{const l=D.links[li],m=D.meta[l[0]];return `<button class="chip fam c${l[3]}" data-li="${li}" title="${CAT[l[3]]}">§${l[1]} ${m[0]}${m[2]==='VGR'?' VGR':''} • ${year(m[0])}</button>`}).join('');
    h+=`<article class="vcard shadow ${key?'key':''}" id="v_${v}"><div class="vh"><span class="vref">${ABBR[S.book]} ${S.chap}:${v}${key?' • Verset clé':''}</span>${L.length?`<button class="lk" data-vi="${vi}">${L.length.toLocaleString('fr')} MSG liés →</button>`:''}</div>
      <p class="vt"><span class="num">${v}</span>${esc(t)}</p>${L.length?`<div class="chips">${ch}${L.length>3?`<button class="chip more" data-vi="${vi}">+${(L.length-3).toLocaleString('fr')} · voir tout →</button>`:''}</div>`:''}</article>`});
  $('bibleView').innerHTML=h;
  $('bibleView').querySelectorAll('[data-vi]').forEach(e=>e.onclick=()=>openVerseSheet(+e.dataset.vi));
  $('bibleView').querySelectorAll('[data-li]').forEach(e=>e.onclick=()=>{const l=D.links[+e.dataset.li];openBrochure(l[0],l[1],l[2])});
  refbar();
  if(flashV){const el=$('v_'+flashV);if(el){el.scrollIntoView({block:'center'});el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),2200)}}else window.scrollTo(0,0);
}
function goBible(b,c,v){S.book=b;S.chap=c;setMode('bible');renderBible(v);if(v!=null){const target=$('v_'+v)?.querySelector('.vt');if(target)target.classList.add('wmb-xref-target')}}
const sortLinks=(a,b)=>D.links[a][3]-D.links[b][3]||D.meta[D.links[a][0]][0].localeCompare(D.meta[D.links[b][0]][0])||D.links[a][1]-D.links[b][1];

// ---------- feuille : paragraphes liés à un verset
let vsState=null;
function openVerseSheet(vi){vsState={vi,cat:-1,zone:0,trad:'all',lim:30};drawVerseSheet();openSheet()}
// déploiement complet : chaque paragraphe lié est affiché en entier, coloré là où il ressemble au verset
async function fillVersePars(vi){const els=[...$('shBody').querySelectorAll('[data-vspt]')];const byZ={};
  els.forEach(e=>{const l=D.links[+e.dataset.vspt],z=D.meta[l[0]][4];if(!available(z)){e.classList.remove('loading');return}(byZ[z]=byZ[z]||[]).push(e)});
  for(const z of Object.keys(byZ)){let d;try{d=await loadZone(+z)}catch(err){continue}
    if(!vsState||vsState.vi!==vi)return;
    byZ[z].forEach(e=>{const l=D.links[+e.dataset.vspt],di=l[0]-D.zoff[z],doc=d.docs[di],para=doc&&doc[4].find(x=>x[0]===l[1]);if(!para){e.classList.remove('loading');return}
      const hits=d.hmap.get(di*100000+l[1])||[];e.classList.remove('loading');e.innerHTML=colorHtml(para[1],hits,vi)})}}
function drawVerseSheet(){
  const {vi,cat,zone,trad,lim}=vsState;let L=linksOfVi(vi).slice().sort(sortLinks);
  const cnt=[0,0,0,0];L.forEach(li=>cnt[D.links[li][3]]++);
  const F=L.filter(li=>{const l=D.links[li],m=D.meta[l[0]];return (cat<0||l[3]===cat)&&(!zone||m[4]===zone)&&(trad==='all'||m[2]===trad)});
  $('shTitle').textContent=`${vref(vi,true)} • ${L.length.toLocaleString('fr')} paragraphes liés`;
  $('shSub').innerHTML=`<span class="serif">« ${esc(vtext(vi))} »</span>`;
  let h=`<div class="fil">`+[-1,0,1,2,3].filter(c=>c<0||cnt[c]).map(c=>`<button class="f ${cat===c?'on':''}" data-c="${c}">${c<0?'Tous':CAT[c]} ${c<0?L.length:cnt[c]}</button>`).join('')+`</div>
   <div class="fil">`+[0,1,2,3,4,5].map(z=>`<button class="f ${zone===z?'on':''}" data-z="${z}">${z?'Zone '+z:'Toutes zones'}</button>`).join('')+
   [['all','SHK+VGR'],['Shekinah','Shekinah'],['VGR','VGR']].map(([k,l])=>`<button class="f ${trad===k?'on':''}" data-t="${k}">${l}</button>`).join('')+`</div>`;
  h+=F.slice(0,lim).map(li=>{const l=D.links[li],m=D.meta[l[0]];return `<div class="li" data-li="${li}"><div class="t1"><span><span class="k c${l[3]}">${CAT[l[3]]}</span>§${l[1]} • ${m[0]} • ${m[2]==='VGR'?'VGR':'Shekinah'}</span><span class="yr">${year(m[0])}</span></div><div class="t2">${esc(m[1])}</div><p class="vs-pt loading" data-vspt="${li}">${l[4]?'… '+esc(l[4])+' …':'Paragraphe lié — ouvrir pour lire'}</p></div>`}).join('');
  if(!F.length)h+='<div style="text-align:center;color:var(--mut);padding:20px">Aucun paragraphe avec ces filtres.</div>';
  if(F.length>lim)h+=`<button class="f" id="vsMore" style="display:block;margin:6px auto">Voir plus (${F.length-lim})</button>`;
  $('shBody').innerHTML=h;$('shBody').scrollTop=0;
  $('shBody').querySelectorAll('[data-c]').forEach(e=>e.onclick=()=>{vsState.cat=+e.dataset.c;drawVerseSheet()});
  $('shBody').querySelectorAll('[data-z]').forEach(e=>e.onclick=()=>{vsState.zone=+e.dataset.z;drawVerseSheet()});
  $('shBody').querySelectorAll('[data-t]').forEach(e=>e.onclick=()=>{vsState.trad=e.dataset.t;drawVerseSheet()});
  $('shBody').querySelectorAll('[data-li]').forEach(e=>e.onclick=()=>{const l=D.links[+e.dataset.li];closeSheet();openBrochure(l[0],l[1],l[2])});
  const mo=$('vsMore');if(mo)mo.onclick=()=>{vsState.lim+=30;drawVerseSheet()};
  fillVersePars(vi);
}

// ---------- vue MSG
function renderMsgList(q){document.querySelector('header .color-tools')?.remove();
  q=(q||'').trim().toLowerCase();const fold=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const fq=fold(q);
  const L=D.meta.map((m,i)=>i).filter(i=>!fq||fold(D.meta[i][0]+' '+D.meta[i][1]).includes(fq));
  let h=`<div class="hint"><b>Onglet MSG</b> : chaque paragraphe est dans sa carte, ses références bibliques en bas. <b>En lecture, pas de couleurs.</b> Appuie sur <b>« Bible liés → »</b> ou sur une référence : les parties concernées se colorent et les versets s’ouvrent en bas. Ferme : les couleurs disparaissent.</div>
    <input class="find" id="mFind" placeholder="Code ou titre (ex. 53-0729, Divinité)…" value="${esc(q)}">`;
  h+=`<div class="list">`+L.slice(0,300).map(i=>{const m=D.meta[i];return `<div class="it shadow" data-d="${i}"><b>${m[0]}${m[2]==='VGR'?' · VGR':''}</b><div style="flex:1;min-width:0"><div style="font-weight:800;font-size:13px">${esc(m[1])}</div><div style="font-size:11px;color:var(--mut)">${m[3]} • Zone ${m[4]} • ${m[5]} §${available(m[4])?'':' • en ligne'}</div></div><span>›</span></div>`}).join('')+`</div>`;
  if(L.length>300)h+=`<div style="text-align:center;color:var(--mut);font-size:12px">${L.length-300} autres — précise la recherche.</div>`;
  $('msgView').innerHTML=h;
  const f=$('mFind');f.oninput=()=>{clearTimeout(f._t);f._t=setTimeout(()=>{renderMsgList(f.value);const g=$('mFind');g.focus();g.setSelectionRange(g.value.length,g.value.length)},300)};
  $('msgView').querySelectorAll('[data-d]').forEach(e=>e.onclick=()=>openBrochure(+e.dataset.d,0,null));
}
function searchHighlightHtml(text,q){const ranges=resultHighlightRanges(text,q);if(!ranges.length)return esc(text);let out='',cursor=0;for(const [a,b] of ranges){if(a>cursor)out+=esc(text.slice(cursor,a));out+='<mark class="search-hit">'+esc(text.slice(a,b))+'</mark>';cursor=b;}return out+esc(text.slice(cursor));}
async function openBrochure(dg,pn,focusVi,focusQuery){
  const m=D.meta[dg],z=m[4];
  if(!available(z)){toast(`Cette brochure est dans la zone ${z}.<br>Démo : seule la zone 1 est intégrée. <a href="${PAGES}parallele.html" target="_blank" style="color:#FFE08A;pointer-events:auto">Version complète en ligne →</a>`,5000);return}
  const d=await loadZone(z);const di=dg-D.zoff[z];const doc=d.docs[di];
  S.doc=dg;S.curP=pn||1;setMode('msg');
  const other=D.meta.findIndex((x,i)=>i!==dg&&x[0]===m[0]&&x[4]===z);
  let h=`<div class="bhead"><div class="s" style="opacity:.55;margin:0 0 4px">${m[0]} • ${m[3]} • ${m[2]==='VGR'?'VGR':'Shekinah'} • Zone ${z}</div><div class="t">${esc(m[1])}</div><div class="s">${doc[4].length} paragraphes • ${new Set(d.hits.filter(x=>x[0]===di).map(x=>x[2])).size} versets rattachés</div>
   <div class="acts"><button class="ghost" id="bList">← Toutes les brochures</button>${other>=0?`<button id="bSw">⇄ ${D.meta[other][2]==='VGR'?'Voir en VGR':'Voir en Shekinah'}</button>`:''}</div></div>`;
  h+=doc[4].map(([n,t])=>{const L=linksOfPara(dg,n);const vis=[...new Set(L.map(li=>D.links[li][2]))];
    const best={};L.forEach(li=>{const l=D.links[li];best[l[2]]=Math.min(best[l[2]]??9,l[3])});
    return `<article class="pcard shadow" id="p_${n}"><div class="ph"><span class="pref">§${n} • ${m[0]} • ${year(m[0])}</span>${vis.length?`<button class="lkb" data-p="${n}">${vis.length} Bible lié${vis.length>1?'s':''} →</button>`:''}</div>
      <p class="pt" id="pt_${n}">${esc(t)}</p>${vis.length?`<div class="chips">${vis.slice(0,8).map(vi=>`<button class="rchip fam c${best[vi]}" data-p="${n}" data-v="${vi}" title="${CAT[best[vi]]}">${vref(vi,true)}</button>`).join('')}${vis.length>8?`<button class="rchip" data-p="${n}">+${vis.length-8}</button>`:''}</div>`:''}</article>`}).join('');
  $('msgView').innerHTML=h;refbar();installDocColors(dg);
  $('bList').onclick=()=>{S.doc=null;renderMsgList('');refbar();window.scrollTo(0,0)};
  if(other>=0)$('bSw').onclick=()=>swapTrad();
  $('msgView').querySelectorAll('.lkb,.rchip').forEach(e=>e.onclick=()=>activatePara(+e.dataset.p,e.dataset.v!=null?+e.dataset.v:null));
  requestAnimationFrame(()=>{const el=pn&&$('p_'+pn);if(el){el.scrollIntoView({block:'center'});el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),2400);
      if(focusVi!=null){try{colorPara(dg,pn,focusVi);const pt=$('pt_'+pn),matched=pt.querySelectorAll('.u');if(matched.length)matched.forEach(mark=>mark.classList.add('wmb-xref-mark'));else pt.classList.add('wmb-xref-target');clearTimeout(window._fadeT);window._fadeT=setTimeout(()=>{pt.classList.add('fading');setTimeout(()=>{if(!act||act.n!==pn||act.dg!==dg)plainPara(dg,pn);pt.classList.remove('fading')},1900)},3800)}catch(e){}}else if(focusQuery){const pt=$('pt_'+pn),source=doc[4].find(x=>x[0]===pn)?.[1];if(pt&&source){pt.innerHTML=searchHighlightHtml(source,focusQuery);pt.classList.add('search-focus');setTimeout(()=>pt.classList.remove('search-focus'),2600);}}}
    else window.scrollTo(0,0)});
}
async function swapTrad(){const dg=S.doc,o=otherOf(dg);if(o<0)return;const cur=visiblePara()||S.curP||1;const z=D.meta[dg][4];const ps=ZD[z].docs[dg-D.zoff[z]][4];const idx=Math.max(0,ps.findIndex(x=>x[0]===cur));
  const map=ALIGN[dg];const match=correspondingParagraph(ps,ZD[z].docs[o-D.zoff[z]][4],idx,map);const target=match.number;toast(`§ ${cur} ${D.meta[dg][2]==='VGR'?'VGR':'Shekinah'} → § ${target} ${D.meta[o][2]==='VGR'?'VGR':'Shekinah'} ${match.estimated?'(passage proche estimé, à vérifier)':'(passage aligné)'}`,2600);await openBrochure(o,target,null)}
function visiblePara(){const top=document.querySelector('header').getBoundingClientRect().bottom+30;for(const p of document.querySelectorAll('.pcard')){if(!p.hidden&&p.getBoundingClientRect().bottom>top)return +p.id.slice(2)}return 0}

window.addEventListener('scroll',()=>{if(S.mode!=='msg'||S.doc==null)return;clearTimeout(window._sc);window._sc=setTimeout(()=>{const p=visiblePara();if(p&&p!==S.curP){S.curP=p;const e=$('curP');if(e)e.textContent='§ '+p}},80)},{passive:true});
// ---------- activer un paragraphe : couleurs + versets en bas
let act=null;
function paraHits(dg,n){const z=D.meta[dg][4],d=ZD[z];return (d.hmap.get((dg-D.zoff[z])*100000+n)||[])}
function colorPara(dg,n,onlyVi){
  const z=D.meta[dg][4],d=ZD[z],p=d.docs[dg-D.zoff[z]][4].find(x=>x[0]===n)[1];const L=p.length;const c=new Int8Array(L).fill(-1);
  paraHits(dg,n).filter(h=>onlyVi==null||h[2]===onlyVi).sort((a,b)=>b[3]-a[3]).forEach(h=>{const sp=h[5];for(let a=0;a<sp.length;a+=2)for(let x=sp[a];x<sp[a+1]&&x<L;x++)c[x]=h[3]});
  let o='',x=0;while(x<L){const k=c[x];let y=x;while(y<L&&c[y]===k)y++;const s=esc(p.slice(x,y));o+=k>=0?`<span class="u c${k}">${s}</span>`:s;x=y}
  $('pt_'+n).innerHTML=o;
}
function plainPara(dg,n){const z=D.meta[dg][4],d=ZD[z];$('pt_'+n).textContent=d.docs[dg-D.zoff[z]][4].find(x=>x[0]===n)[1]}
function activatePara(n,onlyVi){
  if(act)deactivate();
  const dg=S.doc;act={dg,n};colorPara(dg,n,onlyVi);$('p_'+n).classList.add('active');
  document.querySelectorAll(`#p_${n} .rchip`).forEach(e=>e.classList.toggle('sel',onlyVi!=null&&+e.dataset.v===onlyVi));
  const H=paraHits(dg,n);const seen=new Set();const U=H.filter(h=>{if(seen.has(h[2]))return false;seen.add(h[2]);return true}).sort((a,b)=>(onlyVi!=null?(b[2]===onlyVi)-(a[2]===onlyVi):0)||a[3]-b[3]);
  const z=D.meta[dg][4],p=ZD[z].docs[dg-D.zoff[z]][4].find(x=>x[0]===n)[1];
  $('shTitle').textContent=`§${n} • ${D.meta[dg][0]} • ${U.length} verset${U.length>1?'s':''} rattaché${U.length>1?'s':''}`;
  $('shSub').innerHTML=`Les parties concernées sont <b>colorées</b> dans le paragraphe (vert exact · bleu partiel · orange contextuel · rouge erreur). Ferme : les couleurs disparaissent.`;
  $('shBody').innerHTML=U.map(h=>{const vi=h[2],sp=h[5];const fr=[];for(let a=0;a<sp.length;a+=2)fr.push(esc(p.slice(sp[a],sp[a+1])));const nb=linksOfVi(vi).length;
    let extra='';if(h[3]===3&&Array.isArray(h[6]))extra=`<div style="font-size:12.5px;color:var(--c3);font-weight:700;margin-top:4px">✗ Annoncé : ${esc(h[6][1])} = ${vref(h[6][0],true)} — le texte cité est ${vref(vi,true)} (à vérifier)</div>`;
    else if(typeof h[6]==='string')extra=`<div style="font-size:12px;color:var(--c0);font-weight:700;margin-top:4px">Référence donnée : ${esc(h[6])}</div>`;
    return `<div class="vitem" style="${onlyVi===vi?'border-color:var(--blue)':''}"><span class="k c${h[3]}">${CAT[h[3]]}</span><b style="font-size:13px">${vref(vi)}</b>${extra}
      <div class="found"><span style="font:800 10px sans-serif;color:#8A6A3A">TROUVÉ DANS LE PARAGRAPHE :</span><br><b>${fr.join('</b> … <b>')}</b></div>
      <div class="arrow">➜ ${vref(vi)}</div><div class="vbox">« ${esc(vtext(vi))} »</div>
      <div class="vacts"><button data-read="${vi}">📖 Lire dans la Bible</button><button class="l" data-where="${vi}">🔗 Où ailleurs ? ${nb.toLocaleString('fr')} paragraphes</button>${U.length>1?`<button class="l" data-only="${vi}">🎯 Colorer seulement ce verset</button>`:''}</div></div>`}).join('');
  $('shBody').scrollTop=0;
  $('shBody').querySelectorAll('[data-read]').forEach(e=>e.onclick=()=>{const vi=+e.dataset.read;closeSheet();goBible(VB[vi],VC[vi],VV[vi])});
  $('shBody').querySelectorAll('[data-where]').forEach(e=>e.onclick=()=>{const vi=+e.dataset.where;deactivate();openVerseSheet(vi)});
  $('shBody').querySelectorAll('[data-only]').forEach(e=>e.onclick=()=>activatePara(n,+e.dataset.only));
  openSheet();
}
function deactivate(){if(!act)return;const {dg,n}=act;act=null;if(S.doc===dg&&$('pt_'+n)){plainPara(dg,n);$('p_'+n).classList.remove('active');document.querySelectorAll(`#p_${n} .rchip`).forEach(e=>e.classList.remove('sel'))}}

// ---------- feuilles & tiroir
function openSheet(){$('sheet').classList.add('on');$('ov').classList.add('on')}
function closeSheet(){$('sheet').classList.remove('on');$('ov').classList.remove('on');deactivate()}
$('ov').onclick=()=>{closeSheet();closeDrawer()};$('shClose').onclick=closeSheet;
function openBooks(){
  $('shTitle').textContent='Aller au livre';$('shSub').textContent='Ancien Testament • Nouveau Testament';
  const g=(a,b)=>D.books.slice(a,b).map((x,i)=>`<button class="${a+i===S.book?'on':''}" data-b="${a+i}" title="${esc(x[0])}">${ABBR[a+i]}</button>`).join('');
  $('shBody').innerHTML=`<div class="gtitle">Ancien Testament</div><div class="grid">${g(0,39)}</div><div class="gtitle" style="margin-top:14px">Nouveau Testament</div><div class="grid">${g(39,66)}</div>`;
  $('shBody').querySelectorAll('[data-b]').forEach(e=>e.onclick=()=>openChaps(+e.dataset.b));openSheet();
}
function openChaps(b){
  $('shTitle').innerHTML=`<button class="x" id="bk" style="display:inline-flex;align-items:center;justify-content:center;margin-right:8px;width:28px;height:28px">‹</button>${esc(D.books[b][0])} — chapitre`;$('shSub').textContent=`${D.books[b][1].length} chapitres • souligné bleu = contient des versets cités`;
  $('shBody').innerHTML=`<div class="grid">${D.books[b][1].map((vs,i)=>{let has=false;for(let v=1;v<=vs.length&&!has;v++)has=linksOfVi(viOf(b,i+1,v)).length>0;return `<button class="${b===S.book&&i+1===S.chap?'on':''} ${has?'hasl':''}" data-c="${i+1}">${i+1}</button>`}).join('')}</div>`;
  $('bk').onclick=openBooks;$('shBody').querySelectorAll('[data-c]').forEach(e=>e.onclick=()=>openVerses(b,+e.dataset.c));
}
function openVerses(b,c){
  $('shTitle').innerHTML=`<button class="x" id="bk" style="display:inline-flex;align-items:center;justify-content:center;margin-right:8px;width:28px;height:28px">‹</button>${esc(D.books[b][0])} ${c} — verset`;$('shSub').textContent='souligné bleu = cité dans les brochures';
  $('shBody').innerHTML=`<div class="grid">${D.books[b][1][c-1].map((_,i)=>`<button class="${linksOfVi(viOf(b,c,i+1)).length?'hasl':''}" data-v="${i+1}">${i+1}</button>`).join('')}</div>`;
  $('bk').onclick=()=>openChaps(b);$('shBody').querySelectorAll('[data-v]').forEach(e=>e.onclick=()=>{closeSheet();goBible(b,c,+e.dataset.v)});
}
$('refBar').onclick=()=>{if(!D)return;if(S.mode==='bible'){openChaps(S.book);openSheet();}else openDrawer();};
function openDrawer(){drawDrawer('');$('drawer').classList.add('on');$('ov').classList.add('on')}
function closeDrawer(){$('drawer').classList.remove('on');if(!$('sheet').classList.contains('on'))$('ov').classList.remove('on')}
$('btnDrawer').onclick=openDrawer;$('dClose').onclick=closeDrawer;
function drawDrawer(q){
  const fold=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const fq=fold(q.trim());
  const B=D.books.map((b,i)=>i).filter(i=>!fq||fold(D.books[i][0]).includes(fq)||fold(ABBR[i])===fq).slice(0,fq?20:0);
  const M=fq?D.meta.map((m,i)=>i).filter(i=>fold(D.meta[i][0]+' '+D.meta[i][1]).includes(fq)).slice(0,40):[];
  let h=`<div class="dsec">Bible en haut • en lecture</div><div class="dit" data-b="${S.book}" style="background:#EEF2FF;border:2px solid var(--navy)">${esc(D.books[S.book][0])} ${S.chap}<small>${D.books[S.book][1].length} chapitres</small></div>`;
  if(S.doc!=null){const m=D.meta[S.doc];h+=`<div class="dsec">MSG en bas • en lecture</div><div class="dit" data-d="${S.doc}" style="background:var(--ink);color:#fff">${m[0]} ${esc(m[1])}<small>${m[3]} • ${m[5]} §</small></div>`}
  if(B.length)h+=`<div class="dsec">Livres</div>`+B.map(i=>`<div class="dit" data-b="${i}">${esc(D.books[i][0])}<small>${D.books[i][1].length} chapitres</small></div>`).join('');
  if(M.length)h+=`<div class="dsec">Brochures</div>`+M.map(i=>`<div class="dit" data-d="${i}">${D.meta[i][0]} ${esc(D.meta[i][1])}<small>${D.meta[i][3]} • ${D.meta[i][2]==='VGR'?'VGR':'Shekinah'} • Zone ${D.meta[i][4]}</small></div>`).join('');
  if(fq&&!B.length&&!M.length)h+=`<div style="padding:16px;color:var(--mut);font-size:13px">Aucun résultat.</div>`;
  h+=`<div class="dsec">Paramètres</div><div class="dit soon">🖍 Surlignage personnel<small>Bientôt : colorer un passage à ta guise (les couleurs d’analyse restent cachées en lecture)</small></div>`;
  $('dBody').innerHTML=h;
  $('dBody').querySelectorAll('[data-b]').forEach(e=>e.onclick=()=>{closeDrawer();const b=+e.dataset.b;goBible(b,b===S.book?S.chap:1,null)});
  $('dBody').querySelectorAll('[data-d]').forEach(e=>e.onclick=()=>{closeDrawer();openBrochure(+e.dataset.d,0,null)});
}
