  await moveTo(document.querySelector(`#shBody [data-c="${c}"]`));openVerses(b,c);await sleep(800);
  await moveTo(document.querySelector(`#shBody [data-v="${v}"]`));closeSheet();goBible(b,c,v);await sleep(900);
  toast(`2) Chaque verset est dans sa carte. En bas : les paragraphes des brochures qui le citent.`);await sleep(3200);
