// Utiliser l’alignement fourni. À défaut, rechercher un texte proche, jamais le seul numéro.
function correspondingParagraph(source, target, index, mapping){
 if(mapping&&mapping[index]!=null&&target.some(p=>p[0]===mapping[index]))return {number:mapping[index],estimated:false};
 const tokens=text=>new Set((text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().match(/[a-z0-9]+/g)||[]).filter(w=>w.length>3));
 const a=tokens(source[index][1]);let best=-1,number=target[0][0];
 target.forEach((p,j)=>{const b=tokens(p[1]);let common=0;a.forEach(w=>{if(b.has(w))common++;});const score=2*common/(a.size+b.size||1)-0.12*Math.abs(index/Math.max(1,source.length-1)-j/Math.max(1,target.length-1));if(score>best){best=score;number=p[0];}});
 return {number,estimated:true};
}

function colorToolbar(parent, counts, onSelect){
 const box=document.createElement('div');box.className='color-tools';
 const names=['Exact','Partiel','Contextuel','Erreur de référence'];
 box.innerHTML=names.map((n,c)=>`<button type="button" data-color="${c}" aria-pressed="false" style="--filter-color:var(--c${c})">${n} (${counts[c]})</button>`).join('')+'<div class="color-status" role="status">Touchez une couleur pour rassembler ses paragraphes. Retouchez-la pour retrouver la lecture complète.</div>';
 parent.prepend(box);box.querySelectorAll('button').forEach(b=>b.onclick=()=>onSelect(+b.dataset.color,box));return box;
}
function listenSwipe(element, callback){let start=null;
 element.addEventListener('touchstart',e=>{start=null;if(e.touches.length!==1||e.target.closest('input,textarea,select,button,a'))return;const t=e.touches[0];start={x:t.clientX,y:t.clientY,time:Date.now()};},{passive:true});
 element.addEventListener('touchcancel',()=>start=null,{passive:true});
 element.addEventListener('touchend',e=>{if(!start)return;const s=start;start=null;const t=e.changedTouches[0],dx=t.clientX-s.x,dy=t.clientY-s.y;if(Date.now()-s.time<1000&&Math.abs(dx)>75&&Math.abs(dx)>Math.abs(dy)*1.7&&!String(getSelection()))callback(dx);},{passive:true});
}

