function turnChapter(direction){if(!D)return;let b=S.book,c=S.chap+direction;
 if(c>D.books[b][1].length){if(b===D.books.length-1){toast('Fin de la Bible : Apocalypse, dernier chapitre.',2200);return;}b++;c=1;}
 if(c<1){if(b===0){toast('Début de la Bible : Genèse 1.',2200);return;}b--;c=D.books[b][1].length;}
 goBible(b,c,null);window.scrollTo(0,0);}
