let panelMode='bible',panelLimit=100,searchTimer;
const nav=document.createElement('div');nav.className='panel-tabs';nav.innerHTML='<button class="panel-tab" data-panel="bible">'+bibleIcon+'<span>La Bible<small id="panelBibleRef"></small></span></button><button class="panel-tab" data-panel="msg">'+openBookIcon+'<span>Les brochures<small id="panelMsgRef"></small></span></button>';
$('drawer').insertBefore(nav,$('dFind').parentElement);
