openDrawer=function(focusSearch=false){if(!D)return;closeSheet();panelMode=S.mode;panelLimit=100;$('dFind').value='';drawDrawer('');$('drawer').classList.add('on');$('ov').classList.add('on');document.body.classList.add('panel-open');if(focusSearch)setTimeout(()=>$('dFind').focus(),100);};
closeDrawer=function(){$('drawer').classList.remove('on');document.body.classList.remove('panel-open');if(!$('sheet').classList.contains('on'))$('ov').classList.remove('on');};
