function searchFold(t){return String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
drawDrawer=function(q){
 const fq=searchFold(q.trim());nav.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.panel===panelMode));
 $('panelBibleRef').textContent=D.books[S.book][0]+' '+S.chap;
 $('panelMsgRef').textContent=S.doc==null?'Choisir une brochure':D.meta[S.doc][0]+' — '+D.meta[S.doc][1];
 $('dFind').placeholder=panelMode==='bible'?'Livre, référence ou mots du verset…':'Titre, code ou mots du paragraphe…';
 let rows=[];
 if(panelMode==='bible'){
 D.books.forEach((bk,b)=>{if(!fq||searchFold(bk[0]).includes(fq)||searchFold(ABBR[b])===fq)rows.push({kind:'book',b,label:bk[0],short:ABBR[b],sub:(b<39?'Ancien':'Nouveau')+' Testament · '+bk[1].length+' chapitres'});});
 if(fq)D.books.forEach((bk,b)=>bk[1].forEach((vs,c)=>vs.forEach((text,v)=>{const ref=bk[0]+' '+(c+1)+':'+(v+1);if(searchFold(text).includes(fq)||searchFold(ref).includes(fq))rows.push({kind:'verse',b,c:c+1,v:v+1,label:ref,short:ABBR[b],sub:text});})));
 }else{
 D.meta.forEach((m,dg)=>{if(!fq||searchFold(m[0]+' '+m[1]).includes(fq))rows.push({kind:'doc',dg,label:m[1],short:m[0].slice(0,2),sub:m[0]+' · '+(m[2]==='VGR'?'VGR':'Shekinah')+' · '+m[3]+(!available(m[4])?' · version en ligne':'')});});
 if(fq)Object.keys(ZD).forEach(z=>ZD[z].docs.forEach((doc,i)=>doc[4].forEach(([n,text])=>{if(searchFold(text).includes(fq))rows.push({kind:'para',dg:D.zoff[z]+i,n,label:doc[0]+' · § '+n,short:'§'+n,sub:text});})));
 }
 let html=panelMode==='msg'&&fq?'<div class="dsec">Textes recherchés dans les zones déjà chargées ; titres dans toutes les zones.</div>':'';
 html+='<div class="dsec">'+rows.length+' résultat(s)</div>';
 html+=rows.slice(0,panelLimit).map((r,i)=>'<button class="panel-item" data-row="'+i+'"><strong>'+esc(r.short)+'</strong><span>'+esc(r.label)+'<small>'+esc(r.sub.length>220?r.sub.slice(0,220)+'…':r.sub)+'</small></span></button>').join('');
 if(!rows.length)html+='<p>Aucun résultat.</p>';
 if(rows.length>panelLimit)html+='<button class="book-picker" id="panelMore">Afficher la suite</button>';
 $('dBody').innerHTML=html;
 $('dBody').querySelectorAll('[data-row]').forEach(el=>el.onclick=()=>{const r=rows[+el.dataset.row];closeDrawer();if(r.kind==='book'){openChaps(r.b);openSheet();}else if(r.kind==='verse'){goBible(r.b,r.c,r.v);}else openBrochure(r.dg,r.n||0,null);});
 if($('panelMore'))$('panelMore').onclick=()=>{panelLimit+=100;drawDrawer(q);};
};
$('dFind').oninput=e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{panelLimit=100;drawDrawer(e.target.value);},180);};
const paletteState={bible:null,msg:null},paletteScroll={bible:0,msg:0};
function refreshPalette(){if(!D)return;const mode=S.mode,cat=paletteState[mode];const view=$(mode==='bible'?'bibleView':'msgView');
 const cards=[...view.querySelectorAll(mode==='bible'?'.vcard':'.pcard')];let shown=0;
 cards.forEach(card=>{let matches=true;if(cat!==null){const n=+card.id.slice(2);matches=mode==='bible'?linksOfVi(viOf(S.book,S.chap,n)).some(li=>D.links[li][3]===cat):paraHits(S.doc,n).some(h=>h[3]===cat);}card.hidden=!matches;if(matches)shown++;});
 $('legend').querySelectorAll('.lg').forEach((b,c)=>{b.setAttribute('aria-pressed',String(c===cat));b.disabled=mode==='msg'&&S.doc==null;});
 $('paletteStatus').textContent=cat===null?'':shown+' '+(mode==='bible'?'verset(s)':'paragraphe(s)')+' · '+CAT[cat]+' — retouchez pour tout afficher';
 view.querySelector('.empty-filter')?.remove();if(cat!==null&&!shown){const e=document.createElement('div');e.className='empty-filter';e.textContent='Aucun passage ne correspond à cette couleur.';view.prepend(e);}
}
$('legend').querySelectorAll('.lg').forEach((b,c)=>b.onclick=()=>{if(!D||(S.mode==='msg'&&S.doc==null))return;closeSheet();const mode=S.mode;if(paletteState[mode]===null)paletteScroll[mode]=scrollY;paletteState[mode]=paletteState[mode]===c?null:c;refreshPalette();window.scrollTo(0,paletteState[mode]===null?paletteScroll[mode]:0);});
const oldSetMode=setMode;setMode=function(m){oldSetMode(m);refreshPalette();};
