// Recherche unifiée définie dans le module de fonctions.
let searchOverlay=null;
function elasticBubble(el){let start=null,dragged=false;
 el.addEventListener('pointerdown',e=>{if(e.button!==0)return;start={x:e.clientX,y:e.clientY};dragged=false;el.setPointerCapture(e.pointerId);});
 el.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>7)dragged=true;if(dragged){el.classList.add('dragging');el.style.transform='translate('+Math.max(-32,Math.min(32,dx*.45))+'px,'+Math.max(-95,Math.min(12,dy*.6))+'px)';}});
 const release=()=>{if(!start)return;start=null;el.classList.remove('dragging');el.style.transform='';if(dragged){el.dataset.dragged='yes';setTimeout(()=>delete el.dataset.dragged,350);}};
 el.addEventListener('pointerup',release);el.addEventListener('pointercancel',release);
 el.addEventListener('click',e=>{if(el.dataset.dragged){e.preventDefault();e.stopImmediatePropagation();}},true);
}
elasticBubble($('bookFloat'));elasticBubble($('searchFloat'));
let tapStart=null;
const mainReader=document.querySelector('main');
mainReader.addEventListener('pointerdown',e=>{tapStart={x:e.clientX,y:e.clientY,time:Date.now()};},{passive:true});
mainReader.addEventListener('click',e=>{if(!tapStart||Math.hypot(e.clientX-tapStart.x,e.clientY-tapStart.y)>8||Date.now()-tapStart.time>450)return;if(e.target.closest('button,a,input,select,.lk,.rchip,[data-li]')||String(getSelection()))return;if(S.mode==='msg'&&S.doc==null)return;const card=e.target.closest('.vcard,.pcard');if(!card)return;
 const before=card.getBoundingClientRect().top;document.body.classList.toggle('reading-only');requestAnimationFrame(()=>window.scrollBy(0,card.getBoundingClientRect().top-before));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('reading-only');if(searchOverlay)searchOverlay.hidden=true;}});

