const globalLoadedZones=new Set();
const filterMemories=new Map(),selectedParts=new Set([0,1,2,3]);
function allowedSources(){return searchTab==='brochures'?['VGR','SHP']:searchTab==='bible'?['AT','NT']:['VGR','SHP','AT','NT'];}
function saveSearchFilters(){filterMemories.set(searchTab,{sources:[...selectedSources],periods:[...selectedPeriods],parts:[...selectedParts],book:$g('globalBook').value,matchKind,wordForm,sort,ascending});}
function restoreSearchFilters(){const old=filterMemories.get(searchTab);selectedSources.clear();(old?old.sources:allowedSources()).forEach(v=>selectedSources.add(v));selectedPeriods.clear();(old?old.periods:['1947-1952','1953-1958','1959-1965']).forEach(v=>selectedPeriods.add(v));$g('globalBook').value=searchTab==='brochures'?'-1':old?.book||'-1';selectedParts.clear();(old?.parts||[0,1,2,3]).forEach(x=>selectedParts.add(x));matchKind=old?.matchKind||'phrase';wordForm=old?.wordForm||'exact';sort=old?.sort||'relevance';ascending=old?.ascending||false;updateSort();}
const currentMode=()=>matchKind+(wordForm==='variants'?'-v':'');
function yearPeriod(y){return y<=1952?'1947-1952':y<=1958?'1953-1958':y<=1965?'1959-1965':null;}
function paintGlobalFilters(){search.querySelectorAll('[data-mode]').forEach(b=>{const yes=b.dataset.mode===currentMode();b.classList.toggle('on',yes);b.setAttribute('aria-pressed',String(yes));});search.querySelectorAll('[data-part]').forEach(b=>{const yes=selectedParts.has(+b.dataset.part);b.classList.toggle('on',selectedParts.size!==4&&yes);b.setAttribute('aria-pressed',String(yes));});$g('allParts').classList.toggle('on',selectedParts.size===4);const allowed=allowedSources();const all=allowed.every(x=>selectedSources.has(x));$g('globalBook').closest('.global-strip').hidden=searchTab==='brochures';$g('currentBook').hidden=searchTab!=='bible';search.querySelectorAll('[data-source]').forEach(b=>b.hidden=!allowed.includes(b.dataset.source));$g('sourceAll').classList.toggle('on',all);$g('sourceAll').setAttribute('aria-pressed',String(all));search.querySelectorAll('[data-source]').forEach(b=>{const yes=selectedSources.has(b.dataset.source);b.classList.toggle('on',!all&&yes);b.setAttribute('aria-pressed',String(yes));});const allYears=selectedPeriods.size===3;$g('allPeriods').classList.toggle('on',allYears);$g('allPeriods').setAttribute('aria-pressed',String(allYears));search.querySelectorAll('[data-period]').forEach(b=>{const yes=selectedPeriods.has(b.dataset.period);b.classList.toggle('on',!allYears&&yes);b.setAttribute('aria-pressed',String(yes));b.disabled=!selectedSources.has('VGR')&&!selectedSources.has('SHP');});search.querySelectorAll('[data-match]').forEach(b=>{const yes=b.dataset.match===matchKind;b.classList.toggle('on',yes);b.setAttribute('aria-pressed',String(yes));});search.querySelectorAll('[data-form]').forEach(b=>{const yes=b.dataset.form===wordForm;b.classList.toggle('on',yes);b.setAttribute('aria-pressed',String(yes));});}
function invalidateGlobal(){currentGlobalId++;searchRun++;clearTimeout(globalTimer);if(globalEngine)globalEngine.postMessage({type:'cancel'});globalBusy=false;$g('cancelGlobal').hidden=true;$g('globalStatus').textContent='';lastApplied='';}
function scheduleGlobal(){invalidateGlobal();search.querySelectorAll('[data-count]').forEach(b=>b.textContent='—');if($g('workQ')&&$g('workQ').value.trim()){ $g('globalStatus').textContent='Mise à jour de la recherche…';globalTimer=setTimeout(runSearch,30);}else if(!$g('workQ').value.trim())$g('workResults').innerHTML='<p>Tapez votre recherche.</p>';}
$g('sourceAll').onclick=()=>{selectedParts.clear();[0,1,2,3].forEach(x=>selectedParts.add(x));selectedSources.clear();allowedSources().forEach(x=>selectedSources.add(x));$g('globalBook').value='-1';paintGlobalFilters();scheduleGlobal();};
search.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{const v=b.dataset.source;if(selectedSources.size===allowedSources().length){selectedSources.clear();selectedSources.add(v);}else if(selectedSources.has(v)){selectedSources.delete(v);if(!selectedSources.size)allowedSources().forEach(x=>selectedSources.add(x));}else selectedSources.add(v);const book=+$g('globalBook').value;if(book>=0&&!selectedSources.has(book<39?'AT':'NT'))$g('globalBook').value='-1';paintGlobalFilters();scheduleGlobal();});
