let readyResolve;
async function ensureGlobalEngine(){if(engineReady)return;if(engineReadyPromise)return engineReadyPromise;engineReadyPromise=new Promise(r=>readyResolve=r);try{const blob=new Blob(['('+garageGlobalWorker.toString()+')()'],{type:'text/javascript'}),url=URL.createObjectURL(blob);globalEngine=new Worker(url);URL.revokeObjectURL(url);globalEngine.onmessage=e=>handleEngineMessage(e.data);globalEngine.onerror=e=>{e.preventDefault();if(!engineReady){globalEngine.terminate();globalEngine=makeFallback();globalEngine.postMessage({type:'init',books:D.books,abbreviations:ABBR});}else{globalBusy=false;$g('cancelGlobal').hidden=true;$g('globalStatus').textContent='Le moteur a été interrompu. Fermez puis rechargez la démo pour réessayer.';}};}catch(e){globalEngine=makeFallback();}globalEngine.postMessage({type:'init',books:D.books,abbreviations:ABBR});return engineReadyPromise;}
async function handleEngineMessage(m){if(m.type==='ready'){engineReady=true;readyResolve();return;}if(m.type==='need-zone'){try{if(INLINE&&INLINE[m.z])globalEngine.postMessage({type:'zone',z:m.z,blob:INLINE[m.z]});else{const response=await fetch('./data/brochures_z'+m.z+'.json.gz');if(!response.ok)throw Error('Chargement impossible');const buffer=await response.arrayBuffer();globalEngine.postMessage({type:'zone',z:m.z,buffer});}}catch(e){globalEngine.postMessage({type:'zone',z:m.z,error:e.message});}return;}if(m.type==='loaded'){globalLoadedZones.add(m.z);return;}if(m.id!==currentGlobalId)return;if(m.type==='partial'){resultTotal=m.total;resultPage=0;resultPages=m.pages||1;elapsed=m.elapsed;streamZone=m.streamZone||0;streamZoneIndex=m.streamZoneIndex||0;streamZoneCount=m.streamZoneCount||0;streamZoneDone=!!m.streamZoneDone;search.querySelectorAll('[data-count]').forEach(b=>b.textContent=m.counts?m.counts[+b.dataset.count]:'—');results=m.items.map(r=>r.type==='msg'?{...r,dg:D.zoff[r.z]+r.i}:r);$g('globalStatus').textContent=`${m.total} résultat(s) provisoire(s) — ${streamZoneDone?'zone terminée, poursuite en arrière-plan':'zone '+streamZoneIndex+'/'+streamZoneCount+' en cours'} · affichage dès 3 résultats`;renderResults();return;}if(m.type==='counts'){search.querySelectorAll('[data-count]').forEach(b=>b.textContent=m.counts[+b.dataset.count]);if(globalBusy)$g('globalStatus').textContent=m.total+' résultat(s) trouvé(s)…';return;}if(m.type==='progress'){$g('globalStatus').textContent=m.text+' — '+(engineMode==='worker'?'calcul en arrière-plan':'mode compatible');return;}if(m.type==='error'){globalBusy=false;$g('cancelGlobal').hidden=true;$g('globalStatus').textContent='Recherche interrompue : '+m.text;return;}if(m.type==='result'){globalBusy=false;$g('cancelGlobal').hidden=true;streamZone=0;streamZoneIndex=0;streamZoneCount=0;streamZoneDone=true;resultTotal=m.total;resultPage=m.page;resultPages=m.pages||1;elapsed=m.elapsed;search.querySelectorAll('[data-count]').forEach(b=>b.textContent=m.counts?m.counts[+b.dataset.count]:'—');results=m.items.map(r=>r.type==='msg'?{...r,dg:D.zoff[r.z]+r.i}:r);lastApplied=$g('workQ').value.trim();document.dispatchEvent(new CustomEvent('garage-search-complete',{detail:{q:lastApplied,tab:searchTab,total:m.total}}));$g('globalStatus').textContent=(m.cachedZones?'Résultats réutilisés · ':'')+(engineMode==='worker'?'Calcul en arrière-plan':'Mode compatible');renderResults();}}
async function runSearch(){if(!D)return;clearTimeout(globalTimer);const id=++currentGlobalId,q=$g('workQ').value.trim();if(!q){invalidateGlobal();$g('workResults').innerHTML='<p>Tapez votre recherche.</p>';return;}globalBusy=true;lastApplied='';search.querySelectorAll('[data-count]').forEach(b=>b.textContent='…');$g('cancelGlobal').hidden=false;$g('globalStatus').textContent='Préparation de la recherche…';$g('workResults').innerHTML='<p class="work-note">Recherche en cours… Vous pouvez changer les filtres ou annuler.</p>';await ensureGlobalEngine();if(id!==currentGlobalId)return;const required=new Set();D.meta.forEach(m=>{const y=1900+(+m[0].slice(0,2));if(selectedPeriods.has(yearPeriod(y))&&selectedSources.has(m[2]==='VGR'?'VGR':'SHP'))required.add(m[4]);});globalEngine.postMessage({type:'search',id,q,mode:currentMode(),sources:[...selectedSources],periods:[...selectedPeriods],book:+$g('globalBook').value,parts:searchTab==='bible'?[...selectedParts]:[0,1,2,3],zones:[...required].sort().filter(available),sort,ascending});}
