let searchTouch=null;
search.addEventListener('touchstart',e=>{if(e.touches.length!==1||e.target.closest('input,select,textarea,button')){searchTouch=null;return;}const t=e.touches[0];searchTouch={x:t.clientX,y:t.clientY,t:Date.now()};},{passive:true});
