const panel=$('drawer'),extras=document.createElement('section');extras.className='mobile-settings-tools';extras.setAttribute('aria-label','Outils et installation');$('studyPanel').append(extras);for(const b of [...panel.children])if(b.matches('button'))extras.append(b);
// Fermetures de dialogues : intitulé neutre, pas de flèche Retour.
function tidy(){const v=!$('simDashboard').hidden?'dashboard':!$('workSearch').hidden?'search':!$('studyPanel').hidden?'study':'reader';if(document.body.dataset.mobileView!==v)document.body.dataset.mobileView=v;const hide=$('studyPanel').hidden||!document.querySelector('[data-study="settings"].on');if(studyShortcuts.hidden!==hide)studyShortcuts.hidden=hide;if(extras.hidden!==hide)extras.hidden=hide;document.querySelectorAll('#themeClose,#pwaClose').forEach(b=>{if(b.textContent!=='Fermer')b.textContent='Fermer';});}
let restoring=false,busy=0,timer,ready=false,depth=0,last=null,sheetRoute=null,m4Quiet=false;const entries=new Map();
function nbIsOpen(){const n=document.getElementById('nb');return !!(n&&!n.hidden)||(!$('studyPanel').hidden&&!!document.querySelector('[data-study="notes"].on'));}
function snapshot(){const view=!$('simDashboard').hidden?'dashboard':!$('workSearch').hidden?'search':nbIsOpen()?'nb':!$('studyPanel').hidden?'study':'reader';return {view,nb:(view==='nb'&&window.NB&&NB.state)?NB.state():null,reader:{mode:S.mode,book:S.book,chap:S.chap,doc:S.doc,curP:S.curP},scroll:scrollY,searchScroll:$('workSearch').scrollTop,studyScroll:$('studyPanel').scrollTop,dashScroll:$('simDashboard').scrollTop,query:$('workQ').value,tab:$('workSearch').dataset.mode,study:document.querySelector('[data-study].on')?.dataset.study||'notes',drawer:$('drawer').classList.contains('on')?{mode:panelMode,q:$('dFind').value}:null,sheet:$('sheet').classList.contains('on')?sheetRoute:null};}
function key(s){return JSON.stringify([s.view,s.view==='reader'?[s.reader.mode,s.reader.book,s.reader.chap,s.reader.doc]:null,s.view==='search'?s.tab:null,s.view==='study'?s.study:null,s.drawer,s.sheet,s.view==='nb'?(s.nb?[s.nb.ed,s.nb.fs,s.nb.sel]:0):null]);}
function save(){if(!ready||restoring||busy)return;last=snapshot();entries.set(depth,last);history.replaceState({mobileNav:true,depth,snapshot:last},'');}
function commit(){tidy();if(restoring||busy||!D||!$('simStartup').hidden)return;if(!ready){ready=true;last=snapshot();entries.set(0,last);history.replaceState({mobileNav:true,depth:0,snapshot:last},'');return;}const now=snapshot();if(key(now)!==key(last)){const prev=entries.get(depth-1);if(last&&last.view==='nb'&&depth>0&&prev&&key(prev)===key(now)){last=now;m4Quiet=true;try{history.go(-1);}catch(e){m4Quiet=false;}return;}depth++;for(const i of entries.keys())if(i>=depth)entries.delete(i);entries.set(depth,now);history.pushState({mobileNav:true,depth,snapshot:now},'');}last=now;}
